use vstd::prelude::*;

verus! {

spec fn forall_equal(a: Seq<i8>, b: Seq<i8>, result: Seq<bool>) -> bool {
    // For all valid indices, result[i] == (a[i] == b[i])
    |i: int| 0 <= i && i < a.len() ==> result[i] == (a[i] == b[i])
}

fn equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall_equal(a.view(), b.view(), result.view()),
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    result.reserve(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            result.len() == i,
            // For all completed indices, resultant boolean is equality of inputs
            forall_equal(
                a.view().slice(0, i),
                b.view().slice(0, i),
                result.view()
            ),
        decreases n - i,
    {
        let res = a[i] == b[i];
        result.push(res);
        i = i + 1;
    }
    result
}

}
